def reference(arr):
    """Obviously-correct reference: sorted rotation <=> at most one wrap drop."""
    if len(arr) == 0:
        return True
    n = len(arr)
    drops = sum(1 for i in range(n) if arr[i] > arr[(i + 1) % n])
    return drops <= 1

def right_shift(arr, k):
    n = len(arr)
    if n == 0:
        return []
    k = k % n
    if k == 0:
        return list(arr)
    return arr[-k:] + arr[:-k]

@given(st.lists(st.integers(min_value=-100, max_value=100), min_size=1, max_size=10, unique=True),
       st.integers(min_value=0, max_value=20))
def test_all_rotations_of_sorted_are_true(arr, k):
